import torch
import torch.nn as nn
from torch.autograd import Function
from torch.utils.cpp_extension import load_inline

swish_bias_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void swish_bias_add_forward_kernel(const float* x, const float* bias, float* out, int rows, int cols) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < rows * cols) {
        int col = idx % cols;
        float val = x[idx];
        float sig = 1.0f / (1.0f + expf(-val));
        out[idx] = val * sig + bias[col];
    }
}

__global__ void swish_bias_add_backward_kernel(const float* x, const float* grad_out, float* grad_x, int rows, int cols) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < rows * cols) {
        float val = x[idx];
        float sig = 1.0f / (1.0f + expf(-val));
        float sig_deriv = sig * (1.0f - sig);
        grad_x[idx] = grad_out[idx] * (sig + val * sig_deriv);
    }
}

torch::Tensor swish_bias_add_forward(torch::Tensor x, torch::Tensor bias) {
    auto out = torch::empty_like(x);
    int rows = x.size(0);
    int cols = x.size(1);
    int threads = 256;
    int blocks = (rows * cols + threads - 1) / threads;
    swish_bias_add_forward_kernel<<<blocks, threads>>>(x.data_ptr<float>(), bias.data_ptr<float>(), out.data_ptr<float>(), rows, cols);
    return out;
}

torch::Tensor swish_bias_add_backward(torch::Tensor x, torch::Tensor grad_out) {
    auto grad_x = torch::empty_like(x);
    int rows = x.size(0);
    int cols = x.size(1);
    int threads = 256;
    int blocks = (rows * cols + threads - 1) / threads;
    swish_bias_add_backward_kernel<<<blocks, threads>>>(x.data_ptr<float>(), grad_out.data_ptr<float>(), grad_x.data_ptr<float>(), rows, cols);
    return grad_x;
}
"""

swish_bias_add_cpp_source = """
torch::Tensor swish_bias_add_forward(torch::Tensor x, torch::Tensor bias);
torch::Tensor swish_bias_add_backward(torch::Tensor x, torch::Tensor grad_out);
"""

swish_bias_add = load_inline(
    name='swish_bias_add',
    cpp_sources=swish_bias_add_cpp_source,
    cuda_sources=swish_bias_add_source,
    functions=['swish_bias_add_forward', 'swish_bias_add_backward'],
    verbose=False
)

class SwishBiasAddFunction(Function):
    @staticmethod
    def forward(ctx, x, bias):
        ctx.save_for_backward(x, bias)
        return swish_bias_add.swish_bias_add_forward(x, bias)

    @staticmethod
    def backward(ctx, grad_output):
        x, bias = ctx.saved_tensors
        grad_x = swish_bias_add.swish_bias_add_backward(x, grad_output)
        grad_bias = grad_output.sum(dim=0)
        return grad_x, grad_bias

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, num_groups, bias_shape):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.group_norm = nn.GroupNorm(num_groups, out_features)

    def forward(self, x):
        x = self.matmul(x)
        x = SwishBiasAddFunction.apply(x, self.bias)
        x = self.group_norm(x)
        return x
